"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useState } from "react";
import { ArrowRight, X } from "react-feather";
import { Button, Flex, Input, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CloseIcon = uiStyled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const InputCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing16",
  gap: "$gap12",
  width: "100%"
});
const InputField = uiStyled(Input, {
  unstyled: true,
  backgroundColor: "transparent",
  borderWidth: 0,
  outlineStyle: "none",
  padding: 0,
  fontSize: "$h2",
  color: "$neutral1",
  width: "100%",
  textAlign: "left"
});
const MaxButton = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  padding: "$spacing4",
  paddingHorizontal: "$spacing8",
  cursor: "pointer",
  hoverStyle: { opacity: 0.8 }
});
const VaultInfoCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing16",
  gap: "$gap12",
  width: "100%",
  marginTop: "$spacing12",
  marginBottom: "$spacing24"
});
const InfoRow = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const SubmitButton = uiStyled(Button, {
  width: "100%"
});
const ReviewContainer = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing16",
  gap: "$gap16",
  width: "100%",
  marginBottom: "$spacing24"
});
const DisclaimerText = uiStyled(Text, {
  variant: "body4",
  color: "$neutral2",
  textAlign: "left",
  marginBottom: "$spacing16",
  lineHeight: "16px"
});
export default function DepositWithdrawPopupModal({
  vault,
  isModalOpen,
  onClose,
  type = "deposit"
}) {
  const colors = useSporeColors();
  const [step, setStep] = useState("input");
  const [amount, setAmount] = useState("");
  if (!vault) return null;
  const isAmountValid = amount.length > 0 && parseFloat(amount) > 0;
  const isDeposit = type === "deposit";
  const title = isDeposit ? "Deposit" : "Withdraw";
  const handleActionClick = () => {
    if (isAmountValid) {
      setStep("review");
    }
  };
  const handleConfirmClick = () => {
    onClose();
  };
  const handleClose = () => {
    setStep("input");
    setAmount("");
    onClose();
  };
  const currentPosition = 0.01;
  const newPosition = isDeposit ? currentPosition + parseFloat(amount || "0") : Math.max(0, currentPosition - parseFloat(amount || "0"));
  return <Modal
    name="DepositWithdrawModal"
    isModalOpen={isModalOpen}
    onClose={handleClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      {
    /* Header */
  }
      <ModalHeader>
        <Text variant="heading3" color="$neutral1">
          {step === "input" ? title : "Review"}
        </Text>
        <CloseIcon onPress={handleClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      {step === "input" ? <>
          {
    /* Input Section */
  }
          <Flex flexDirection="row" justifyContent="space-between" mb="$spacing8" px="$spacing4">
            <Text variant="body2" color="$neutral2">
              {title} {vault.token.symbol}
            </Text>
            <Flex flexDirection="row" gap="$gap8" alignItems="center">
              <Text variant="body2" color="$neutral2">
                8.85 {vault.token.symbol}
              </Text>
              <MaxButton onPress={() => setAmount("8.85")}>
                <Text variant="buttonLabel4" color="$neutral2">
                  MAX
                </Text>
              </MaxButton>
            </Flex>
          </Flex>

          <InputCard>
            <Flex flexDirection="row" alignItems="center" justifyContent="space-between">
              <InputField
    placeholder="0.00"
    autoFocus
    placeholderTextColor="$neutral3"
    value={amount}
    onChangeText={setAmount}
  />
              <Flex
    flexDirection="row"
    alignItems="center"
    gap="$gap8"
    backgroundColor="$surface1"
    px="$spacing8"
    py="$spacing4"
    borderRadius="$roundedFull"
  >
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
                <Text variant="buttonLabel1" color="$neutral1">
                  {vault.token.symbol}
                </Text>
              </Flex>
            </Flex>
            <Text variant="body3" color="$neutral2">
              ${(parseFloat(amount || "0") * 0.99).toFixed(2)}
            </Text>
          </InputCard>

          {
    /* Vault Info Section */
  }
          <VaultInfoCard>
            <Flex flexDirection="row" alignItems="center" gap="$gap12" mb="$spacing8">
              <Flex
    width={40}
    height={40}
    backgroundColor="$accent1"
    borderRadius="$roundedFull"
    alignItems="center"
    justifyContent="center"
  >
                {
    /** Placeholder bigger logo if needed, reusing PortfolioLogo for now but bigger */
  }
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={40}
  />
              </Flex>
              <Flex flexDirection="column">
                <Text variant="body1" color="$neutral1">
                  {vault.name}
                </Text>
                <Flex
    flexDirection="row"
    alignItems="center"
    gap="$gap4"
    backgroundColor="$surface3"
    px="$spacing6"
    py="$spacing2"
    borderRadius="$rounded8"
    width="fit-content"
  >
                  {
    /* Placeholder logic for protocol name */
  }
                  <Text variant="body2" color="$neutral2">
                    SparkDAO
                  </Text>
                  {
    /* Arrow icon if needed */
  }
                </Flex>
              </Flex>
            </Flex>

            <InfoRow>
              <Text variant="body3" color="$neutral2">
                My Position ({vault.token.symbol})
              </Text>
              {
    /* Mock data for user position */
  }
              <Flex flexDirection="row" alignItems="center" gap="$gap4">
                <Text variant="body3" color="$neutral1">
                  {currentPosition}
                </Text>
                <ArrowRight size={12} color={colors.neutral2.val} />
                <Text variant="body3" color="$neutral1">
                  {newPosition.toFixed(2)}
                </Text>
              </Flex>
            </InfoRow>

            <InfoRow>
              <Text variant="body3" color="$neutral2">
                APY
              </Text>
              <Flex flexDirection="row" alignItems="center" gap="$gap4">
                <Text variant="body3" color="$greenVibrant">
                  {vault.apy.toFixed(2)}%
                </Text>
                {
    /* Sparkle icon would go here */
  }
              </Flex>
            </InfoRow>

            <InfoRow>
              <Text variant="body3" color="$neutral2">
                Exposure
              </Text>
              {
    /* Exposure icons placeholder */
  }
              <Flex flexDirection="row" gap="-8px">
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="BTC"
    tokenName="Bitcoin"
    images={[]}
    size={16}
  />
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="ETH"
    tokenName="Ethereum"
    images={[]}
    size={16}
  />
              </Flex>
            </InfoRow>
          </VaultInfoCard>

          {
    /* Action Button */
  }
          <SubmitButton size="large" emphasis="primary" disabled={!isAmountValid} onPress={handleActionClick}>
            {isAmountValid ? title : "Enter an amount"}
          </SubmitButton>
        </> : <>
          {
    /* Review Step */
  }
          <ReviewContainer>
            <Flex flexDirection="row" alignItems="center" gap="$gap12">
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
              <Text variant="heading3" color="$neutral1">
                {vault.name}
              </Text>
            </Flex>

            <Flex gap="$gap4">
              <Text variant="body2" color="$neutral2">
                {title}
              </Text>
              <Flex flexDirection="row" alignItems="flex-end" gap="$gap8">
                <Text variant="heading2" color="$neutral1">
                  {amount} {vault.token.symbol}
                </Text>
                <Flex backgroundColor="$surface3" borderRadius="$rounded8" px="$spacing8" py="$spacing4" mb="$spacing4">
                  <Text variant="body4" color="$neutral2">
                    ${(parseFloat(amount) * 0.99).toFixed(2)}
                  </Text>
                </Flex>
              </Flex>
              <Flex alignSelf="flex-end">
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={24}
  />
              </Flex>
            </Flex>

            <Flex gap="$gap12" width="100%">
              <InfoRow>
                <Text variant="body3" color="$neutral2">
                  {title} ({vault.token.symbol})
                </Text>
                <Flex flexDirection="row" alignItems="center" gap="$gap4">
                  <Text variant="body3" color="$neutral2">
                    {currentPosition}
                  </Text>
                  <ArrowRight size={12} color={colors.neutral2.val} />
                  <Text variant="body3" color="$neutral1">
                    {newPosition.toFixed(2)}
                  </Text>
                </Flex>
              </InfoRow>

              <InfoRow>
                <Text variant="body3" color="$neutral2">
                  APY
                </Text>
                <Flex flexDirection="row" alignItems="center" gap="$gap4">
                  <Text variant="body3" color="$greenVibrant">
                    {vault.apy.toFixed(2)}%
                  </Text>
                </Flex>
              </InfoRow>

              <InfoRow>
                <Text variant="body3" color="$neutral2">
                  Exposure
                </Text>
                <Flex flexDirection="row" gap="-8px">
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="BTC"
    tokenName="Bitcoin"
    images={[]}
    size={16}
  />
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol="ETH"
    tokenName="Ethereum"
    images={[]}
    size={16}
  />
                </Flex>
              </InfoRow>
            </Flex>
          </ReviewContainer>

          <DisclaimerText>
            By confirming this transaction, you agree to the{" "}
            <Text variant="body4" color="$neutral2" style={{ textDecoration: "underline" }}>
              Terms of Use
            </Text>{" "}
            and the services provisions relating to the Morpho Vault.
          </DisclaimerText>

          <SubmitButton size="large" emphasis="primary" onPress={handleConfirmClick}>
            Confirm
          </SubmitButton>
        </>}
    </Modal>;
}
